head.b:skin:
/*
-----------------------------------------------
Blogger Template Style
Name:      Roushan Pro
Version:   1.0.0
Designer:  Roushan Gupta
URL:       (your blog url)
License:   Fully owned by the blog owner.
           No third-party credits, no encrypted
           scripts, no external CSS/JS libraries.
----------------------------------------------- */

/* Variable definitions
<Variable name="keycolor" description="Main Color" type="color" hideEditor="true" default="$(main.color)" value="#30bd9b"/>
<Variable name="followByEmail" description="Follow By Email Text" type="string" hideEditor="true" default="Get new posts delivered straight to your inbox." value="Get new posts delivered straight to your inbox."/>

<Group description="Theme Colors" selector="body">
  <Variable name="main.color" description="Accent Color (Buttons / Links)" type="color" default="#30bd9b" value="#30bd9b"/>
  <Variable name="dark.color" description="Dark / Navy Color (Hero / Footer)" type="color" default="#0a0f1e" value="#0a0f1e"/>
  <Variable name="body.background.color" description="Body Background" type="color" default="#f5f7f9" value="#f5f7f9"/>
  <Variable name="body.text.color" description="Body Text Color" type="color" default="#3f4756" value="#3f4756"/>
  <Variable name="title.color" description="Heading Color" type="color" default="#0b1220" value="#0b1220"/>
  <Variable name="posts.background.color" description="Card Background" type="color" default="#ffffff" value="#ffffff"/>
  <Variable name="footer.dark.color" description="Footer Background" type="color" default="#070b14" value="#070b14"/>
</Group>

<Group description="Typography" selector="body">
  <Variable name="body.text.font" description="Body Font" type="font" default="15px Poppins, sans-serif" value="15px Poppins, sans-serif"/>
</Group>

<Variable name="body.background" description="Background" hideEditor="true" type="background" color="$(body.background.color)" default="$(color) url() repeat scroll top left" value="$(color) url() repeat scroll top left"/>
<Variable name="body.link.color" description="Body Link Color" hideEditor="true" type="color" default="$(main.color)" value="#30bd9b"/>
<Variable name="posts.title.color" description="Post Title Color" hideEditor="true" type="color" default="$(title.color)" value="#0b1220"/>
<Variable name="posts.text.color" description="Post Text Color" hideEditor="true" type="color" default="$(body.text.color)" value="#3f4756"/>
<Variable name="tabs.font" description="Font 2" hideEditor="true" type="font" default="14px Poppins, sans-serif" value="14px Poppins, sans-serif"/>
*/

/* =========================================================
   1. DESIGN TOKENS
   ========================================================= */
:root {
  --accent: $(main.color);
  --navy: $(dark.color);
  --bg: $(body.background.color);
  --card: $(posts.background.color);
  --text: $(body.text.color);
  --title: $(title.color);
  --muted: #77809333;
  --muted-text: #6b7487;
  --line: #e7ecf2;
  --footer-bg: $(footer.dark.color);
  --radius: 16px;
  --radius-sm: 10px;
  --radius-lg: 22px;
  --shadow-sm: 0 1px 3px rgba(10, 15, 30, .06);
  --shadow: 0 6px 24px rgba(10, 15, 30, .08);
  --shadow-lg: 0 18px 50px rgba(10, 15, 30, .16);
  --accent-soft: rgba(48, 189, 155, .12);
  --accent-soft-2: rgba(48, 189, 155, .22);
  --font-body: 'Poppins', 'Noto Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Arial, sans-serif;
  --font-head: 'Poppins', 'Noto Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Arial, sans-serif;
  --header-h: 66px;
  --container: 1200px;
}

html[data-theme='dark'] {
  --navy: #e8edf5;
  --bg: #0b101c;
  --card: #111828;
  --text: #c3cbda;
  --title: #f0f4fa;
  --muted-text: #8b95a9;
  --line: #202b40;
  --accent-soft: rgba(48, 189, 155, .16);
  --accent-soft-2: rgba(48, 189, 155, .28);
  --shadow-sm: 0 1px 3px rgba(0, 0, 0, .4);
  --shadow: 0 8px 28px rgba(0, 0, 0, .45);
  --shadow-lg: 0 18px 50px rgba(0, 0, 0, .55);
  --footer-bg: #080d18;
}

/* =========================================================
   2. RESET & BASE
   ========================================================= */
*, *::before, *::after { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; scroll-behavior: smooth; }

body {
  margin: 0;
  padding: 0;
  font: $(body.text.font);
  font-family: var(--font-body);
  color: var(--text);
  background: var(--bg);
  line-height: 1.75;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  transition: background .3s ease, color .3s ease;
  overflow-x: hidden;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-head);
  color: var(--title);
  line-height: 1.3;
  margin: 0 0 .5em;
  font-weight: 700;
}

p { margin: 0 0 1.1em; }

a { color: var(--accent); text-decoration: none; transition: color .2s ease; }
a:hover { color: var(--title); }

img { max-width: 100%; height: auto; border: 0; vertical-align: middle; }

ul, ol { padding-left: 1.3em; margin: 0 0 1.1em; }

button {
  font-family: inherit;
  cursor: pointer;
  border: 0;
  background: none;
  color: inherit;
}

input, textarea, select { font-family: inherit; }

svg.ic { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; vertical-align: middle; flex: none; }
svg.ic-f { fill: currentColor; stroke: none; }

.container { max-width: var(--container); margin: 0 auto; padding: 0 22px; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); border: 0; }
.clearfix::after { content: ""; display: table; clear: both; }

.skip-link {
  position: absolute; left: -9999px; top: 0; z-index: 9999;
  background: var(--accent); color: #fff; padding: 10px 18px; border-radius: 0 0 10px 0; font-weight: 600;
}
.skip-link:focus { left: 0; }

::selection { background: var(--accent); color: #fff; }

:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; border-radius: 4px; }

/* Scrollbar */
::-webkit-scrollbar { width: 11px; height: 11px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: #c3ccd8; border-radius: 8px; border: 3px solid var(--bg); }
html[data-theme='dark'] ::-webkit-scrollbar-thumb { background: #2c3a52; border-color: var(--bg); }

/* =========================================================
   3. BUTTONS
   ========================================================= */
.btn {
  display: inline-flex; align-items: center; gap: 9px;
  padding: 13px 26px; border-radius: 999px;
  font-weight: 600; font-size: .92rem; line-height: 1;
  transition: transform .2s ease, box-shadow .2s ease, background .2s ease, color .2s ease, border-color .2s ease;
  white-space: nowrap;
}
.btn svg.ic { width: 17px; height: 17px; }
.btn-primary { background: var(--accent); color: #fff; box-shadow: 0 8px 22px rgba(48, 189, 155, .35); }
.btn-primary:hover { color: #fff; transform: translateY(-2px); box-shadow: 0 12px 28px rgba(48, 189, 155, .45); filter: brightness(.96); }
.btn-ghost { border: 1.5px solid rgba(255, 255, 255, .35); color: #fff; background: rgba(255, 255, 255, .06); backdrop-filter: blur(6px); }
.btn-ghost:hover { color: #fff; border-color: #fff; background: rgba(255, 255, 255, .14); }
.btn-dark { background: var(--title); color: var(--card); }
.btn-dark:hover { color: var(--card); filter: brightness(1.15); }

/* =========================================================
   4. READING PROGRESS + BACK TO TOP
   ========================================================= */
.progress-bar {
  position: fixed; top: 0; left: 0; height: 3px; width: 0;
  background: linear-gradient(90deg, var(--accent), #6fe3c3);
  z-index: 1002; transition: width .1s linear;
  display: none;
}
body.is-item .progress-bar { display: block; }

.to-top {
  position: fixed; right: 22px; bottom: 24px; z-index: 901;
  width: 46px; height: 46px; border-radius: 50%;
  background: var(--accent); color: #fff;
  display: flex; align-items: center; justify-content: center;
  box-shadow: 0 10px 26px rgba(48, 189, 155, .4);
  opacity: 0; visibility: hidden; transform: translateY(12px);
  transition: opacity .25s ease, transform .25s ease, visibility .25s;
}
.to-top.show { opacity: 1; visibility: visible; transform: translateY(0); }
.to-top:hover { color: #fff; filter: brightness(.94); transform: translateY(-3px); }

/* =========================================================
   5. HEADER
   ========================================================= */
.site-header {
  position: sticky; top: 0; z-index: 1000;
  background: rgba(255, 255, 255, .86);
  -webkit-backdrop-filter: blur(14px); backdrop-filter: blur(14px);
  border-bottom: 1px solid var(--line);
  transition: box-shadow .25s ease, background .3s ease;
}
html[data-theme='dark'] .site-header { background: rgba(11, 16, 28, .88); }
.site-header.scrolled { box-shadow: var(--shadow-sm); }

.header-inner { display: flex; align-items: center; gap: 26px; min-height: var(--header-h); }

/* Brand */
.brand-logo img { max-height: 40px; width: auto; display: block; }
.brand-text { display: inline-flex; align-items: center; gap: 11px; }
.brand-mark {
  width: 40px; height: 40px; border-radius: 12px; flex: none;
  display: inline-flex; align-items: center; justify-content: center;
  background: linear-gradient(135deg, var(--accent), #1d8f74);
  color: #fff; font-weight: 800; font-size: 1.15rem;
  box-shadow: 0 6px 16px rgba(48, 189, 155, .35);
}
.brand-name {
  font-family: var(--font-head); font-weight: 700; font-size: 1.22rem;
  color: var(--title); letter-spacing: -.02em; line-height: 1.15; max-width: 260px;
}
.brand-name:hover { color: var(--accent); }

/* Menu */
.main-menu { margin-left: auto; }
.menu-list { display: flex; align-items: center; gap: 4px; list-style: none; margin: 0; padding: 0; }
.menu-list > li { position: relative; }
.menu-list > li > a {
  display: block; padding: 9px 15px; border-radius: 9px;
  color: var(--text); font-weight: 500; font-size: .93rem;
}
.menu-list > li > a:hover { color: var(--accent); background: var(--accent-soft); }

/* Header actions */
.header-actions { display: flex; align-items: center; gap: 8px; }
.icon-btn {
  width: 41px; height: 41px; border-radius: 11px; flex: none;
  display: inline-flex; align-items: center; justify-content: center;
  color: var(--text); border: 1px solid var(--line); background: var(--card);
  transition: all .2s ease;
}
.icon-btn:hover { color: var(--accent); border-color: var(--accent); background: var(--accent-soft); }
.icon-btn .ic { width: 19px; height: 19px; }
.hamburger-btn { display: none; }
html[data-theme='dark'] .moon-ic { display: none; }
html:not([data-theme='dark']) .sun-ic { display: none; }

/* Mobile drawer */
.drawer-backdrop {
  position: fixed; inset: 0; z-index: 1100; background: rgba(7, 11, 20, .55);
  opacity: 0; visibility: hidden; transition: opacity .25s ease, visibility .25s;
}
.drawer-backdrop.open { opacity: 1; visibility: visible; }
.mobile-drawer {
  position: fixed; top: 0; right: 0; bottom: 0; z-index: 1101;
  width: min(84vw, 340px); background: var(--card);
  transform: translateX(100%); transition: transform .3s cubic-bezier(.4, 0, .2, 1);
  display: flex; flex-direction: column; box-shadow: var(--shadow-lg);
}
.mobile-drawer.open { transform: translateX(0); }
.drawer-head {
  display: flex; align-items: center; justify-content: space-between;
  padding: 18px 22px; border-bottom: 1px solid var(--line);
}
.drawer-head span { font-weight: 700; color: var(--title); font-size: 1.05rem; }
.drawer-links { padding: 14px; overflow-y: auto; flex: 1; }
.drawer-links ul { list-style: none; margin: 0; padding: 0; }
.drawer-links a {
  display: flex; align-items: center; gap: 10px;
  padding: 13px 16px; margin-bottom: 4px; border-radius: 12px;
  color: var(--text); font-weight: 500;
}
.drawer-links a:hover { background: var(--accent-soft); color: var(--accent); }
.drawer-foot { padding: 18px 22px; border-top: 1px solid var(--line); font-size: .82rem; color: var(--muted-text); }

/* =========================================================
   6. HERO (Homepage)
   ========================================================= */
.hero {
  position: relative; overflow: hidden;
  background:
    radial-gradient(900px 480px at 85% -10%, rgba(48, 189, 155, .25), transparent 60%),
    radial-gradient(700px 420px at -10% 110%, rgba(48, 189, 155, .12), transparent 55%),
    linear-gradient(160deg, #0a0f1e 0%, #0c1526 55%, #0a1a1f 100%);
  color: #fff;
}
.hero::before {
  content: ""; position: absolute; inset: 0; opacity: .5;
  background-image: linear-gradient(rgba(255, 255, 255, .035) 1px, transparent 1px), linear-gradient(90deg, rgba(255, 255, 255, .035) 1px, transparent 1px);
  background-size: 44px 44px;
  -webkit-mask-image: radial-gradient(70% 70% at 50% 30%, #000, transparent);
  mask-image: radial-gradient(70% 70% at 50% 30%, #000, transparent);
}
.hero-inner {
  position: relative; z-index: 1;
  display: grid; grid-template-columns: 1.15fr .85fr; gap: 40px;
  align-items: center; padding-top: 74px; padding-bottom: 84px;
}
.hero-badge {
  display: inline-flex; align-items: center; gap: 9px;
  padding: 8px 16px; border-radius: 999px;
  background: rgba(48, 189, 155, .14); border: 1px solid rgba(48, 189, 155, .35);
  color: #7fe7cb; font-size: .8rem; font-weight: 600; letter-spacing: .04em; text-transform: uppercase;
}
.hero-badge::before { content: ""; width: 7px; height: 7px; border-radius: 50%; background: var(--accent); box-shadow: 0 0 0 4px rgba(48, 189, 155, .25); animation: pulse 2.2s infinite; }
@keyframes pulse { 0%, 100% { box-shadow: 0 0 0 3px rgba(48, 189, 155, .3); } 50% { box-shadow: 0 0 0 7px rgba(48, 189, 155, .08); } }
.hero-copy h1 {
  color: #fff; font-size: clamp(2.05rem, 4.6vw, 3.3rem);
  font-weight: 800; letter-spacing: -.025em; line-height: 1.14; margin: 22px 0 18px;
}
.hero-copy h1 .hl { color: var(--accent); position: relative; white-space: nowrap; }
.hero-copy h1 .hl svg { position: absolute; left: 0; bottom: -6px; width: 100%; height: 10px; }
.hero-copy p { color: #b9c3d4; font-size: 1.04rem; max-width: 54ch; margin-bottom: 30px; }
.hero-cta { display: flex; flex-wrap: wrap; gap: 14px; }

/* Hero side card */
.hero-side { position: relative; min-height: 380px; }
.hero-card {
  position: relative; z-index: 2;
  background: rgba(255, 255, 255, .07); border: 1px solid rgba(255, 255, 255, .14);
  -webkit-backdrop-filter: blur(12px); backdrop-filter: blur(12px);
  border-radius: var(--radius-lg); padding: 26px; margin: 40px 20px 0;
  box-shadow: var(--shadow-lg);
  animation: floaty 6s ease-in-out infinite;
}
@keyframes floaty { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-10px); } }
.hero-card-top { display: flex; align-items: center; gap: 12px; margin-bottom: 16px; }
.hero-ava {
  width: 46px; height: 46px; border-radius: 50%; flex: none;
  display: flex; align-items: center; justify-content: center;
  background: linear-gradient(135deg, var(--accent), #1d8f74); color: #fff; font-weight: 700;
}
.hero-card-top b { color: #fff; font-size: .95rem; display: block; line-height: 1.3; }
.hero-card-top small { color: #93a0b5; font-size: .78rem; }
.hero-card-line { height: 9px; border-radius: 6px; background: rgba(255, 255, 255, .16); margin-bottom: 9px; }
.hero-card-line.w80 { width: 80%; } .hero-card-line.w60 { width: 60%; }
.hero-card-tag {
  display: inline-block; margin-top: 8px; padding: 5px 12px; border-radius: 999px;
  background: rgba(48, 189, 155, .18); color: #7fe7cb; font-size: .74rem; font-weight: 600;
}
.hero-chip {
  position: absolute; z-index: 3; display: inline-flex; align-items: center; gap: 8px;
  padding: 10px 16px; border-radius: 999px; font-size: .82rem; font-weight: 600;
  background: rgba(255, 255, 255, .09); border: 1px solid rgba(255, 255, 255, .16);
  color: #e7edf5; -webkit-backdrop-filter: blur(8px); backdrop-filter: blur(8px);
}
.hero-chip svg.ic { width: 16px; height: 16px; color: var(--accent); }
.chip-1 { top: 0; left: -8px; animation: floaty 5s .3s ease-in-out infinite; }
.chip-2 { top: 44%; right: -10px; animation: floaty 7s .8s ease-in-out infinite; }
.chip-3 { bottom: -6px; left: 14%; animation: floaty 6s 1.2s ease-in-out infinite; }

@media (prefers-reduced-motion: reduce) {
  .hero-card, .hero-chip, .hero-badge::before { animation: none; }
  html { scroll-behavior: auto; }
}

/* =========================================================
   7. TOPICS (Homepage)
   ========================================================= */
.topics { padding: 64px 0 10px; }
.topics-inner { display: grid; grid-template-columns: repeat(3, 1fr); gap: 22px; }
.topic-card {
  position: relative; overflow: hidden;
  background: var(--card); border: 1px solid var(--line); border-radius: var(--radius);
  padding: 30px 28px; box-shadow: var(--shadow-sm);
  transition: transform .25s ease, box-shadow .25s ease, border-color .25s ease;
}
.topic-card::after {
  content: ""; position: absolute; top: 0; left: 0; right: 0; height: 3px;
  background: linear-gradient(90deg, var(--accent), rgba(48, 189, 155, 0));
  opacity: 0; transition: opacity .25s ease;
}
.topic-card:hover { transform: translateY(-5px); box-shadow: var(--shadow); border-color: rgba(48, 189, 155, .4); }
.topic-card:hover::after { opacity: 1; }
.topic-icon {
  width: 54px; height: 54px; border-radius: 15px; margin-bottom: 18px;
  display: inline-flex; align-items: center; justify-content: center;
}
.topic-icon svg.ic { width: 25px; height: 25px; }
.t-business { background: rgba(59, 130, 246, .13); color: #3b82f6; }
.t-tech { background: rgba(139, 92, 246, .13); color: #8b5cf6; }
.t-ai { background: var(--accent-soft-2); color: #17a583; }
.topic-card h3 { font-size: 1.18rem; margin-bottom: 8px; }
.topic-card p { font-size: .9rem; color: var(--muted-text); margin-bottom: 16px; }
.topic-link { font-weight: 600; font-size: .88rem; display: inline-flex; align-items: center; gap: 7px; }
.topic-link svg.ic { width: 15px; height: 15px; transition: transform .2s ease; }
.topic-link:hover svg.ic { transform: translateX(4px); }

/* =========================================================
   8. CONTENT LAYOUT
   ========================================================= */
.content-wrapper { display: grid; grid-template-columns: minmax(0, 1fr) 330px; gap: 40px; padding-top: 56px; padding-bottom: 70px; align-items: start; }
.content-wrapper.no-sidebar { grid-template-columns: minmax(0, 1fr); }

.section-head { margin-bottom: 30px; }
.section-title {
  font-size: 1.65rem; font-weight: 800; letter-spacing: -.02em;
  display: flex; align-items: center; gap: 14px; margin-bottom: 6px;
}
.section-title::before { content: ""; width: 5px; height: 26px; border-radius: 4px; background: linear-gradient(180deg, var(--accent), #1d8f74); flex: none; }
.section-sub { color: var(--muted-text); font-size: .93rem; margin: 0; }

/* Query message (search / label) */
.queryMessage { margin-bottom: 26px; }
.query-info {
  display: block; padding: 14px 20px; border-radius: var(--radius-sm);
  background: var(--accent-soft); border: 1px solid rgba(48, 189, 155, .3);
  color: var(--title); font-size: .92rem;
}
.query-info a { font-weight: 600; margin-left: 8px; white-space: nowrap; }
.queryEmpty { text-align: center; padding: 60px 20px; color: var(--muted-text); }

/* =========================================================
   9. POST GRID (Cards)
   ========================================================= */
.post-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 26px; }

.post-card {
  display: flex; flex-direction: column; overflow: hidden;
  background: var(--card); border: 1px solid var(--line); border-radius: var(--radius);
  box-shadow: var(--shadow-sm);
  transition: transform .25s ease, box-shadow .25s ease, border-color .25s ease;
}
.post-card:hover { transform: translateY(-5px); box-shadow: var(--shadow); border-color: rgba(48, 189, 155, .38); }

.card-thumb { position: relative; display: block; aspect-ratio: 16 / 9; overflow: hidden; background: linear-gradient(135deg, #10203a, #0d2b26); }
.card-thumb img { width: 100%; height: 100%; object-fit: cover; transition: transform .5s cubic-bezier(.2, .6, .2, 1); }
.post-card:hover .card-thumb img { transform: scale(1.06); }
.card-noimg { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; color: rgba(255, 255, 255, .55); }
.card-noimg svg.ic { width: 42px; height: 42px; }
.card-label {
  position: absolute; left: 14px; top: 14px; z-index: 2;
  padding: 5px 13px; border-radius: 999px;
  background: rgba(10, 15, 30, .62); color: #fff; font-size: .72rem; font-weight: 600;
  letter-spacing: .05em; text-transform: uppercase;
  -webkit-backdrop-filter: blur(6px); backdrop-filter: blur(6px);
  border: 1px solid rgba(255, 255, 255, .18);
}

.card-body { display: flex; flex-direction: column; flex: 1; padding: 22px 24px 24px; }
.card-meta { display: flex; align-items: center; flex-wrap: wrap; gap: 8px 14px; font-size: .78rem; color: var(--muted-text); margin-bottom: 10px; }
.card-meta span { display: inline-flex; align-items: center; gap: 5px; }
.card-meta svg.ic { width: 14px; height: 14px; }
.card-title { font-size: 1.08rem; line-height: 1.42; margin: 0 0 10px; font-weight: 700; letter-spacing: -.01em; }
.card-title a { color: var(--title); }
.card-title a:hover { color: var(--accent); }
.card-snippet {
  font-size: .87rem; color: var(--muted-text); margin: 0 0 16px; flex: 1;
  display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden;
}
.card-more { display: inline-flex; align-items: center; gap: 7px; font-size: .85rem; font-weight: 600; }
.card-more svg.ic { width: 15px; height: 15px; transition: transform .2s ease; }
.card-more:hover svg.ic { transform: translateX(4px); }

/* First card featured (desktop) */
@media (min-width: 981px) {
  .post-grid .post-card:first-child { grid-column: 1 / -1; flex-direction: row; }
  .post-grid .post-card:first-child .card-thumb { flex: 1 1 52%; aspect-ratio: auto; min-height: 280px; }
  .post-grid .post-card:first-child .card-body { flex: 1 1 48%; justify-content: center; padding: 34px 36px; }
  .post-grid .post-card:first-child .card-title { font-size: 1.5rem; }
}

/* Pagination */
.blog-pager { display: flex; justify-content: space-between; align-items: center; gap: 14px; margin-top: 42px; flex-wrap: wrap; }
.blog-pager a, .blog-pager span {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 12px 24px; border-radius: 999px; font-weight: 600; font-size: .9rem;
  border: 1.5px solid var(--line); color: var(--text); background: var(--card);
  transition: all .2s ease;
}
.blog-pager a:hover { border-color: var(--accent); color: var(--accent); background: var(--accent-soft); }
.blog-pager span { opacity: .45; cursor: default; }
.pager-label { font-size: .78rem; text-transform: uppercase; letter-spacing: .08em; color: var(--muted-text); width: 100%; text-align: center; margin-bottom: -6px; }
.blog-pager .pg-older { margin-left: auto; background: var(--title); color: var(--card); border-color: var(--title); }
.blog-pager .pg-older:hover { color: var(--card); filter: brightness(1.18); }

/* =========================================================
   10. SINGLE POST
   ========================================================= */
.item-post { background: var(--card); border: 1px solid var(--line); border-radius: var(--radius); box-shadow: var(--shadow-sm); overflow: hidden; }
.post-inner { padding: 38px 44px 44px; }

/* Breadcrumb */
.breadcrumb { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; font-size: .8rem; color: var(--muted-text); margin-bottom: 22px; }
.breadcrumb a { color: var(--muted-text); font-weight: 500; }
.breadcrumb a:hover { color: var(--accent); }
.breadcrumb svg.ic { width: 13px; height: 13px; opacity: .6; }
.breadcrumb .bc-here { color: var(--accent); font-weight: 600; }

.label-chips { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 16px; }
.label-chip {
  padding: 5px 14px; border-radius: 999px; font-size: .74rem; font-weight: 600;
  background: var(--accent-soft); color: #17a583; letter-spacing: .04em; text-transform: uppercase;
  border: 1px solid rgba(48, 189, 155, .25);
}
html[data-theme='dark'] .label-chip { color: #6fe3c3; }
.label-chip:hover { background: var(--accent-soft-2); color: #17a583; }
html[data-theme='dark'] .label-chip:hover { color: #8ff0d6; }

.post-title { font-size: clamp(1.55rem, 3.2vw, 2.25rem); font-weight: 800; letter-spacing: -.022em; line-height: 1.22; margin-bottom: 18px; }

.post-meta { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 18px; padding-bottom: 24px; border-bottom: 1px solid var(--line); margin-bottom: 30px; font-size: .84rem; color: var(--muted-text); }
.post-meta span { display: inline-flex; align-items: center; gap: 6px; }
.post-meta svg.ic { width: 15px; height: 15px; color: var(--accent); }
.post-meta a { color: var(--muted-text); font-weight: 600; }
.post-meta a:hover { color: var(--accent); }

/* Table of contents */
.toc-box {
  margin: 0 0 30px; border: 1px solid var(--line); border-radius: var(--radius-sm);
  background: linear-gradient(180deg, rgba(48, 189, 155, .05), transparent);
  overflow: hidden;
}
.toc-head { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 13px 20px; cursor: pointer; user-select: none; }
.toc-head b { display: flex; align-items: center; gap: 9px; font-size: .9rem; color: var(--title); }
.toc-head svg.ic { width: 17px; height: 17px; color: var(--accent); }
.toc-head .toc-arrow { transition: transform .25s ease; color: var(--muted-text); }
.toc-box.collapsed .toc-arrow { transform: rotate(-90deg); }
.toc-body { padding: 4px 20px 16px 24px; border-top: 1px solid var(--line); }
.toc-body ul { list-style: none; margin: 8px 0 0; padding: 0; }
.toc-body li { margin: 0; }
.toc-body a { display: block; padding: 5px 0 5px 14px; font-size: .88rem; color: var(--text); border-left: 2px solid var(--line); transition: all .18s ease; }
.toc-body li.lvl-3 a { padding-left: 30px; font-size: .84rem; }
.toc-body a:hover { color: var(--accent); border-left-color: var(--accent); }
.toc-box.collapsed .toc-body { display: none; }

/* Post body typography */
.post-body { font-size: 1.02rem; color: var(--posts.text.color); }
.post-body img { border-radius: var(--radius-sm); cursor: zoom-in; margin: 6px auto; }
.post-body h2 { font-size: 1.55rem; margin: 1.6em 0 .6em; letter-spacing: -.015em; }
.post-body h3 { font-size: 1.25rem; margin: 1.5em 0 .55em; }
.post-body h4 { font-size: 1.08rem; margin: 1.4em 0 .5em; }
.post-body a { text-decoration: underline; text-decoration-color: rgba(48, 189, 155, .45); text-underline-offset: 3px; }
.post-body a:hover { text-decoration-color: var(--accent); }
.post-body blockquote {
  margin: 1.6em 0; padding: 18px 26px; border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
  background: var(--accent-soft); border-left: 4px solid var(--accent);
  font-style: italic; color: var(--title);
}
.post-body blockquote p:last-child { margin-bottom: 0; }
.post-body ul li, .post-body ol li { margin-bottom: .4em; }
.post-body pre {
  position: relative; background: #0d1526; color: #dce6f5; border-radius: var(--radius-sm);
  padding: 18px 20px; overflow-x: auto; font-size: .86rem; line-height: 1.7; margin: 1.5em 0;
}
.post-body pre code { background: none; padding: 0; color: inherit; font-size: inherit; }
.post-body code {
  background: var(--accent-soft); color: #0e8c6f; border-radius: 6px;
  padding: 2px 8px; font-size: .87em; font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
}
html[data-theme='dark'] .post-body code { color: #7fe7cb; }
.post-body table { width: 100%; border-collapse: collapse; margin: 1.5em 0; font-size: .92rem; display: block; overflow-x: auto; }
.post-body th, .post-body td { border: 1px solid var(--line); padding: 10px 14px; text-align: left; }
.post-body th { background: var(--accent-soft); color: var(--title); font-weight: 600; }
.post-body hr { border: 0; height: 1px; background: var(--line); margin: 2.2em 0; }
.copy-code-btn {
  position: absolute; top: 10px; right: 10px; padding: 6px 12px; border-radius: 8px;
  background: rgba(255, 255, 255, .12); color: #cfe3da; font-size: .72rem; font-weight: 600;
  display: inline-flex; align-items: center; gap: 6px; transition: background .2s ease;
}
.copy-code-btn:hover { background: rgba(255, 255, 255, .24); }
.copy-code-btn svg.ic { width: 13px; height: 13px; }
.copy-code-btn.done { color: #6fe3c3; }

/* Share bar */
.post-share { margin: 34px 0 8px; padding-top: 26px; border-top: 1px solid var(--line); }
.share-label { font-size: .8rem; font-weight: 700; text-transform: uppercase; letter-spacing: .09em; color: var(--muted-text); margin-bottom: 13px; }
.share-links { display: flex; flex-wrap: wrap; gap: 10px; list-style: none; margin: 0; padding: 0; }
.share-links li { margin: 0; }
.share-links a {
  width: 42px; height: 42px; border-radius: 12px;
  display: inline-flex; align-items: center; justify-content: center;
  color: #fff; transition: transform .2s ease, filter .2s ease;
}
.share-links a:hover { transform: translateY(-3px); filter: brightness(1.08); color: #fff; }
.share-links svg.ic, .share-links svg.ic-f { width: 18px; height: 18px; }
.sh-fb { background: #1877f2; } .sh-x { background: #14171c; } .sh-li { background: #0a66c2; }
.sh-wa { background: #25d366; } .sh-tg { background: #229ed9; } .sh-cp { background: var(--title); color: var(--card); }
.sh-cp:hover { color: var(--card); }

/* Post footer extras */
.post-tags { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; margin: 26px 0 0; }
.post-tags .tag-label { font-size: .8rem; font-weight: 700; text-transform: uppercase; letter-spacing: .08em; color: var(--muted-text); display: inline-flex; align-items: center; gap: 6px; }
.post-tags .tag-label svg.ic { width: 15px; height: 15px; color: var(--accent); }

/* Author box */
.author-box {
  display: flex; gap: 22px; align-items: flex-start; margin-top: 34px;
  padding: 28px; border-radius: var(--radius);
  background: linear-gradient(135deg, rgba(48, 189, 155, .09), rgba(48, 189, 155, .02));
  border: 1px solid rgba(48, 189, 155, .3);
}
.author-photo {
  width: 74px; height: 74px; border-radius: 50%; flex: none;
  display: flex; align-items: center; justify-content: center;
  background: linear-gradient(135deg, var(--accent), #1d8f74); color: #fff;
  font-size: 1.6rem; font-weight: 800; box-shadow: 0 10px 24px rgba(48, 189, 155, .35);
}
.author-label { font-size: .72rem; text-transform: uppercase; letter-spacing: .1em; color: var(--accent); font-weight: 700; }
.author-name { font-size: 1.15rem; margin: 3px 0 6px; }
.author-bio { font-size: .9rem; color: var(--muted-text); margin-bottom: 10px; }
.author-links { display: flex; flex-wrap: wrap; gap: 16px; font-size: .85rem; font-weight: 600; }

/* Related posts */
.related-posts { margin-top: 46px; }
.rp-title { font-size: 1.3rem; font-weight: 800; letter-spacing: -.015em; display: flex; align-items: center; gap: 12px; margin-bottom: 20px; }
.rp-title::before { content: ""; width: 5px; height: 22px; border-radius: 4px; background: linear-gradient(180deg, var(--accent), #1d8f74); }
.rp-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 18px; }
.rp-card { overflow: hidden; background: var(--card); border: 1px solid var(--line); border-radius: var(--radius-sm); box-shadow: var(--shadow-sm); transition: transform .22s ease, box-shadow .22s ease; }
.rp-card:hover { transform: translateY(-4px); box-shadow: var(--shadow); }
.rp-thumb { display: block; aspect-ratio: 16 / 10; overflow: hidden; background: linear-gradient(135deg, #10203a, #0d2b26); }
.rp-thumb img { width: 100%; height: 100%; object-fit: cover; transition: transform .4s ease; }
.rp-card:hover .rp-thumb img { transform: scale(1.06); }
.rp-body { padding: 14px 16px 16px; }
.rp-body h4 { font-size: .92rem; line-height: 1.45; margin: 0; font-weight: 600; }
.rp-body h4 a { color: var(--title); }
.rp-body h4 a:hover { color: var(--accent); }
.rp-body time { display: block; margin-top: 7px; font-size: .74rem; color: var(--muted-text); }

/* Post navigation */
.post-nav { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; margin-top: 40px; }
.post-nav a {
  display: flex; flex-direction: column; gap: 5px; padding: 18px 22px;
  border-radius: var(--radius-sm); border: 1px solid var(--line); background: var(--card);
  box-shadow: var(--shadow-sm); transition: all .2s ease;
}
.post-nav a:hover { border-color: var(--accent); box-shadow: var(--shadow); }
.post-nav a.pn-next { text-align: right; align-items: flex-end; }
.post-nav small { font-size: .72rem; text-transform: uppercase; letter-spacing: .09em; color: var(--muted-text); display: inline-flex; align-items: center; gap: 6px; }
.post-nav small svg.ic { width: 13px; height: 13px; color: var(--accent); }
.post-nav b { font-size: .94rem; color: var(--title); line-height: 1.4; }
.post-nav a:hover b { color: var(--accent); }

/* =========================================================
   11. COMMENTS
   ========================================================= */
.comments-wrap { margin-top: 46px; }
.comments-title { font-size: 1.3rem; font-weight: 800; display: flex; align-items: center; gap: 12px; margin-bottom: 22px; }
.comments-title::before { content: ""; width: 5px; height: 22px; border-radius: 4px; background: linear-gradient(180deg, var(--accent), #1d8f74); }
.comments { color: var(--text); }
.comments .comments-content, .comments .comment-thread { font-size: .94rem; }
.comments .comment-thread ol { list-style: none; padding: 0; margin: 0; }
.comments .comment-thread ol ol { padding-left: 30px; }
.comments .comment { border: 1px solid var(--line); background: var(--card); border-radius: var(--radius-sm); padding: 16px 20px; margin-bottom: 14px; list-style: none; }
.comments .comment .comment { border-color: rgba(48, 189, 155, .28); background: linear-gradient(180deg, rgba(48, 189, 155, .045), transparent); }
.comments .comment-header .user, .comments .comment-header .user a { font-style: normal; font-weight: 700; color: var(--title); font-size: .92rem; }
.comments .comment-header .datetime a { font-size: .76rem; color: var(--muted-text); }
.comments .comment-content { margin: 8px 0 6px; line-height: 1.7; font-size: .92rem; }
.comments .comment-actions a, .comments .continue a { font-size: .78rem; font-weight: 600; color: var(--accent); margin-right: 12px; display: inline-block; }
.comments .avatar-image-container { width: 40px; height: 40px; border-radius: 50%; overflow: hidden; border: 2px solid var(--accent-soft-2); float: left; margin-right: 14px; }
.comments .avatar-image-container img { width: 100%; height: 100%; object-fit: cover; }
.comments .comment-replybox-single, .comments .comment-replybox-thread { margin: 10px 0 0 54px; }
.comments .comment-form h4, .comment-form h4 { font-size: 1.05rem; padding: 0; margin: 0 0 14px; }
#comment-editor { border-radius: var(--radius-sm); background: #fff; }
.comment-form p { font-size: .84rem; color: var(--muted-text); }
.comments .thread-toggle { margin-bottom: 8px; }
.comments .loadmore a, .comments .loadmore.loaded a { font-weight: 600; }
.paging-control-container { font-size: .84rem; }
.paging-control-container a { margin-right: 10px; }

/* =========================================================
   12. SIDEBAR
   ========================================================= */
.sidebar .widget, .sidebar-widget { background: var(--card); border: 1px solid var(--line); border-radius: var(--radius); padding: 26px 26px 24px; box-shadow: var(--shadow-sm); margin-bottom: 26px; }
.widget-title { font-size: 1.02rem; font-weight: 700; letter-spacing: -.01em; display: flex; align-items: center; gap: 11px; margin: 0 0 18px; padding-bottom: 14px; border-bottom: 1px solid var(--line); }
.widget-title::before { content: ""; width: 4px; height: 20px; border-radius: 4px; background: var(--accent); flex: none; }

/* About widget */
.about-me { text-align: center; }
.about-ava {
  width: 92px; height: 92px; margin: 0 auto 16px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  background: linear-gradient(135deg, var(--accent), #1d8f74); color: #fff;
  font-size: 2rem; font-weight: 800; box-shadow: 0 12px 30px rgba(48, 189, 155, .35);
}
.about-me h4 { font-size: 1.15rem; margin-bottom: 2px; }
.about-me .about-role { color: var(--accent); font-size: .78rem; font-weight: 600; text-transform: uppercase; letter-spacing: .08em; }
.about-me p { font-size: .88rem; color: var(--muted-text); margin: 12px 0 16px; }
.about-social { display: flex; justify-content: center; gap: 9px; }
.about-social a {
  width: 38px; height: 38px; border-radius: 11px; display: inline-flex; align-items: center; justify-content: center;
  background: var(--accent-soft); color: #17a583; transition: all .2s ease;
}
.about-social a:hover { background: var(--accent); color: #fff; transform: translateY(-3px); }
.about-social svg.ic, .about-social svg.ic-f { width: 17px; height: 17px; }

/* Popular posts */
.pp-item { display: flex; gap: 14px; align-items: center; padding: 12px 0; border-bottom: 1px dashed var(--line); }
.pp-item:last-child { border-bottom: 0; padding-bottom: 0; }
.pp-item:first-child { padding-top: 0; }
.pp-thumb { position: relative; width: 66px; height: 66px; border-radius: 13px; overflow: hidden; flex: none; background: linear-gradient(135deg, #10203a, #0d2b26); display: block; }
.pp-thumb img { width: 100%; height: 100%; object-fit: cover; }
.pp-noimg { width: 100%; height: 100%; display: flex; align-items: center; justify-content: center; color: rgba(255, 255, 255, .5); }
.pp-noimg svg.ic { width: 22px; height: 22px; }
.pp-rank {
  position: absolute; top: 5px; left: 5px; width: 19px; height: 19px; border-radius: 6px;
  background: rgba(10, 15, 30, .72); color: #fff; font-size: .66rem; font-weight: 700;
  display: flex; align-items: center; justify-content: center;
}
.pp-body { min-width: 0; }
.pp-title { font-size: .9rem; line-height: 1.45; margin: 0 0 4px; font-weight: 600; }
.pp-title a { color: var(--title); }
.pp-title a:hover { color: var(--accent); }
.pp-date { font-size: .74rem; color: var(--muted-text); display: inline-flex; align-items: center; gap: 5px; }
.pp-date svg.ic { width: 12px; height: 12px; }

/* Labels */
.sidebar .widget ul, .footer-widget ul { list-style: none; margin: 0; padding: 0; }
.label-list li { margin-bottom: 4px; }
.label-list a {
  display: flex; align-items: center; justify-content: space-between; gap: 10px;
  padding: 9px 14px; border-radius: 10px; color: var(--text); font-size: .9rem; font-weight: 500;
  border: 1px solid transparent; transition: all .18s ease;
}
.label-list a:hover { background: var(--accent-soft); color: var(--accent); border-color: rgba(48, 189, 155, .3); }
.label-count {
  background: var(--accent-soft-2); color: #17a583; font-size: .72rem; font-weight: 700;
  min-width: 26px; height: 22px; padding: 0 8px; border-radius: 999px;
  display: inline-flex; align-items: center; justify-content: center;
}
html[data-theme='dark'] .label-count { color: #8ff0d6; }
.cloud-label a {
  display: inline-flex; align-items: center; gap: 7px; margin: 0 7px 9px 0;
  padding: 7px 15px; border-radius: 999px; border: 1px solid var(--line);
  font-size: .82rem; font-weight: 500; color: var(--text); transition: all .18s ease;
}
.cloud-label a:hover { background: var(--accent); border-color: var(--accent); color: #fff; }
.cloud-label .label-count { background: none; padding: 0; min-width: auto; color: inherit; opacity: .7; }

/* =========================================================
   13. STATS (Homepage)
   ========================================================= */
.stats { background: var(--navy); color: #fff; position: relative; overflow: hidden; }
.stats::before {
  content: ""; position: absolute; inset: 0; opacity: .35;
  background: radial-gradient(600px 300px at 15% 0%, rgba(48, 189, 155, .3), transparent 60%), radial-gradient(600px 300px at 90% 100%, rgba(48, 189, 155, .2), transparent 60%);
}
.stats-inner { position: relative; z-index: 1; display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; padding-top: 54px; padding-bottom: 54px; }
.stat { text-align: center; padding: 10px; }
.stat-num { font-size: 2.5rem; font-weight: 800; color: var(--accent); line-height: 1.1; display: block; letter-spacing: -.02em; font-family: var(--font-head); }
.stat-label { font-size: .85rem; color: #9aa6bb; font-weight: 500; }

/* =========================================================
   14. FOOTER
   ========================================================= */
.site-footer { background: var(--footer-bg); color: #98a3b8; margin-top: 0; }
.footer-widgets { display: grid; grid-template-columns: 1.3fr 1fr 1fr; gap: 44px; padding-top: 64px; padding-bottom: 50px; }
.footer-widget .widget-title, .footer-widget h3 { color: #fff; font-size: 1rem; border-bottom: 1px solid rgba(255, 255, 255, .1); }
.footer-widget .widget-title::before { background: var(--accent); }
.footer-about p { font-size: .9rem; line-height: 1.8; }
.footer-brand { display: inline-flex; align-items: center; gap: 11px; margin-bottom: 16px; }
.footer-brand .brand-mark { box-shadow: none; }
.footer-brand span b { color: #fff; font-size: 1.15rem; }
.footer-widget a { color: #98a3b8; }
.footer-widget a:hover { color: var(--accent); }
.footer-widget li { margin-bottom: 9px; }
.footer-widget li a { display: inline-flex; align-items: center; gap: 8px; font-size: .9rem; }
.footer-widget li a::before { content: "›"; color: var(--accent); font-weight: 700; }
.footer-social { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 18px; }
.footer-social a {
  width: 40px; height: 40px; border-radius: 12px; display: inline-flex; align-items: center; justify-content: center;
  background: rgba(255, 255, 255, .07); border: 1px solid rgba(255, 255, 255, .12); color: #cdd6e4;
  transition: all .2s ease;
}
.footer-social a:hover { background: var(--accent); border-color: var(--accent); color: #fff; transform: translateY(-3px); }
.footer-social svg.ic, .footer-social svg.ic-f { width: 17px; height: 17px; }
.footer-bottom { border-top: 1px solid rgba(255, 255, 255, .09); }
.footer-bottom-inner { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 10px; min-height: 66px; font-size: .82rem; }
.footer-bottom-inner a { color: #cdd6e4; font-weight: 600; }
.footer-bottom-inner a:hover { color: var(--accent); }
.copyright { color: #7f8aa0; }
.copyright a { color: #cdd6e4; }

/* =========================================================
   15. SEARCH OVERLAY
   ========================================================= */
.search-overlay {
  position: fixed; inset: 0; z-index: 1200; padding: 9vh 18px 18px;
  background: rgba(7, 11, 20, .66); -webkit-backdrop-filter: blur(8px); backdrop-filter: blur(8px);
  opacity: 0; visibility: hidden; transition: opacity .25s ease, visibility .25s;
  overflow-y: auto;
}
.search-overlay.open { opacity: 1; visibility: visible; }
.search-panel {
  max-width: 680px; margin: 0 auto; background: var(--card); border: 1px solid var(--line);
  border-radius: var(--radius-lg); box-shadow: var(--shadow-lg); overflow: hidden;
  transform: translateY(-14px) scale(.98); transition: transform .25s ease;
}
.search-overlay.open .search-panel { transform: translateY(0) scale(1); }
.search-box { display: flex; align-items: center; gap: 13px; padding: 18px 22px; border-bottom: 1px solid var(--line); }
.search-box > svg.ic { color: var(--accent); width: 21px; height: 21px; }
#search-input { flex: 1; border: 0; outline: none; background: none; color: var(--title); font-size: 1.05rem; font-family: inherit; min-width: 0; }
#search-input::placeholder { color: var(--muted-text); }
.search-kbd { font-size: .68rem; color: var(--muted-text); border: 1px solid var(--line); border-radius: 6px; padding: 3px 7px; font-weight: 600; flex: none; }
.search-results { max-height: 56vh; overflow-y: auto; padding: 10px; }
.search-hint { text-align: center; color: var(--muted-text); font-size: .86rem; padding: 26px 10px; margin: 0; }
.sr-item { display: flex; gap: 14px; align-items: center; padding: 12px; border-radius: 13px; transition: background .18s ease; }
.sr-item:hover { background: var(--accent-soft); }
.sr-thumb { width: 58px; height: 58px; border-radius: 11px; object-fit: cover; flex: none; background: linear-gradient(135deg, #10203a, #0d2b26); }
.sr-title { font-size: .92rem; font-weight: 600; color: var(--title); line-height: 1.4; margin: 0 0 3px; }
.sr-date { font-size: .74rem; color: var(--muted-text); }

/* Lightbox */
.lightbox { position: fixed; inset: 0; z-index: 1300; background: rgba(5, 8, 15, .9); display: flex; align-items: center; justify-content: center; padding: 26px; opacity: 0; visibility: hidden; transition: opacity .25s ease, visibility .25s; cursor: zoom-out; }
.lightbox.open { opacity: 1; visibility: visible; }
.lightbox img { max-width: 100%; max-height: 92vh; border-radius: var(--radius-sm); box-shadow: var(--shadow-lg); }

/* =========================================================
   16. 404 PAGE
   ========================================================= */
.error-wrap { text-align: center; padding: 70px 24px 80px; }
.error-code { font-size: clamp(6rem, 16vw, 10rem); font-weight: 800; line-height: 1; letter-spacing: -.04em; background: linear-gradient(135deg, var(--accent), #1d8f74); -webkit-background-clip: text; background-clip: text; color: transparent; }
.error-wrap h3 { font-size: 1.4rem; margin: 14px 0 8px; }
.error-wrap p { color: var(--muted-text); max-width: 46ch; margin: 0 auto 26px; }
.error-actions { display: flex; justify-content: center; flex-wrap: wrap; gap: 13px; }

/* =========================================================
   17. REVEAL ANIMATION
   ========================================================= */
.reveal { opacity: 0; transform: translateY(18px); transition: opacity .6s ease, transform .6s ease; }
.reveal.in { opacity: 1; transform: translateY(0); }
@media (prefers-reduced-motion: reduce) { .reveal { opacity: 1; transform: none; transition: none; } }

/* =========================================================
   18. RESPONSIVE
   ========================================================= */
@media (max-width: 1080px) {
  .content-wrapper { grid-template-columns: minmax(0, 1fr) 300px; gap: 30px; }
  .rp-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 980px) {
  .main-menu { display: none; }
  .hamburger-btn { display: inline-flex; }
  .hero-inner { grid-template-columns: 1fr; padding-top: 58px; padding-bottom: 64px; }
  .hero-side { display: none; }
  .content-wrapper { grid-template-columns: minmax(0, 1fr); }
  .post-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 18px; }
  .topics-inner { grid-template-columns: 1fr; }
  .stats-inner { grid-template-columns: repeat(2, 1fr); }
  .footer-widgets { grid-template-columns: 1fr 1fr; gap: 34px; }
  .footer-widgets .footer-about { grid-column: 1 / -1; }
  .post-inner { padding: 30px 26px 34px; }
}

@media (max-width: 640px) {
  .container { padding: 0 16px; }
  .post-grid { grid-template-columns: 1fr; }
  .rp-grid { grid-template-columns: 1fr; }
  .post-nav { grid-template-columns: 1fr; }
  .post-nav a.pn-next { text-align: left; align-items: flex-start; }
  .author-box { flex-direction: column; }
  .footer-widgets { grid-template-columns: 1fr; }
  .footer-bottom-inner { justify-content: center; text-align: center; }
  .to-top { right: 14px; bottom: 16px; }
  .brand-name { font-size: 1.05rem; max-width: 52vw; }
  .hero-copy h1 { font-size: clamp(1.8rem, 8vw, 2.3rem); }
  .section-title { font-size: 1.35rem; }
  .post-title { font-size: 1.45rem; }
  .comments .comment-thread ol ol { padding-left: 16px; }
  .comments .comment-replybox-single, .comments .comment-replybox-thread { margin-left: 0; }
}

/* =========================================================
   19. PRINT
   ========================================================= */
@media print {
  .site-header, .site-footer, .to-top, .post-share, .comments-wrap, .related-posts, .progress-bar, .search-overlay, .mobile-drawer, .drawer-backdrop, .hero-side { display: none !important; }
  body { background: #fff; color: #000; }
  .item-post { border: 0; box-shadow: none; }
}

head.b:template-skin:

body#layout { background: #eef1f5; padding: 0; }
body#layout .header-actions, body#layout .progress-bar, body#layout .to-top,
body#layout .search-overlay, body#layout .mobile-drawer, body#layout .drawer-backdrop,
body#layout .lightbox, body#layout .hero-side, body#layout .skip-link,
body#layout .footer-note { display: none !important; }
body#layout .site-header { background: #dfe9f5; border: 1px dashed #5b7ba0; border-radius: 8px; padding: 6px; margin: 8px 0; }
body#layout .hero, body#layout .topics, body#layout .stats { background: #e3f4ee; border: 1px dashed #30bd9b; border-radius: 8px; margin: 8px 0; padding: 6px; }
body#layout .content-wrapper, body#layout .footer-widgets { background: transparent; border: 0; }
body#layout .footer-widgets { background: #e8ebf2; border-radius: 8px; padding: 6px; margin-top: 8px; }
body#layout ul { list-style: none; margin: 0; padding: 0; }
body#layout .widget { border: 1px solid #d5dbe6; border-radius: 8px; margin-bottom: 6px; }

body.script:
/**/
(function () {
  'use strict';
  var d = document, w = window, body = d.body;
  var HOME = (w.RP_HOME || '').replace(/\/+$/, '');

  function $(s, c) { return (c || d).querySelector(s); }
  function $$(s, c) { return Array.prototype.slice.call((c || d).querySelectorAll(s)); }
  function esc(s) { var div = d.createElement('div'); div.textContent = s || ''; return div.innerHTML; }

  /* ----- Current year ----- */
  $$('.rp-year').forEach(function (el) { el.textContent = new Date().getFullYear(); });

  /* ----- Header state / progress / to-top ----- */
  var header = $('#site-header');
  var progress = $('#progress-bar');
  var toTop = $('#to-top');

  function onScroll() {
    var y = w.scrollY || d.documentElement.scrollTop || 0;
    if (header) { if (y > 8) { header.classList.add('scrolled'); } else { header.classList.remove('scrolled'); } }
    if (toTop) { if (y > 600) { toTop.classList.add('show'); } else { toTop.classList.remove('show'); } }
    if (progress) {
      var h = d.documentElement;
      var max = h.scrollHeight - h.clientHeight;
      var p = max > 0 ? y / max : 0;
      progress.style.width = (p * 100) + '%';
    }
  }
  w.addEventListener('scroll', onScroll, { passive: true });
  onScroll();
  if (toTop) { toTop.addEventListener('click', function () { w.scrollTo({ top: 0, behavior: 'smooth' }); }); }

  /* ----- Dark / light mode ----- */
  var themeBtn = $('#theme-toggle');
  var themeMeta = $('#meta-theme-color');
  function applyMeta() {
    if (themeMeta) { themeMeta.setAttribute('content', d.documentElement.getAttribute('data-theme') === 'dark' ? '#0b101c' : '#ffffff'); }
  }
  if (themeBtn) {
    themeBtn.addEventListener('click', function () {
      var root = d.documentElement;
      var dark = root.getAttribute('data-theme') === 'dark';
      if (dark) { root.removeAttribute('data-theme'); } else { root.setAttribute('data-theme', 'dark'); }
      try { localStorage.setItem('rp-theme', dark ? 'light' : 'dark'); } catch (e) {}
      applyMeta();
    });
  }
  applyMeta();

  /* ----- Mobile drawer ----- */
  var drawer = $('#mobile-drawer'), backdrop = $('#drawer-backdrop'), drawerLinks = $('#drawer-links');
  var menu = $('#main-menu-nav');
  if (drawerLinks && menu) { drawerLinks.innerHTML = '<ul>' + menu.innerHTML + '</ul>'; }
  function openDrawer() { if (!drawer) { return; } drawer.classList.add('open'); if (backdrop) { backdrop.classList.add('open'); } body.style.overflow = 'hidden'; }
  function closeDrawer() { if (!drawer) { return; } drawer.classList.remove('open'); if (backdrop) { backdrop.classList.remove('open'); } body.style.overflow = ''; }
  function openSearch() {
    var ov = $('#search-overlay'); if (!ov) { return; }
    ov.classList.add('open'); body.style.overflow = 'hidden';
    setTimeout(function () { var i = $('#search-input'); if (i) { i.focus(); } }, 80);
  }
  function closeSearch() {
    var ov = $('#search-overlay'); if (!ov) { return; }
    ov.classList.remove('open'); body.style.overflow = '';
  }
  var dOpen = $('#drawer-open-btn'), dClose = $('#drawer-close-btn');
  if (dOpen) { dOpen.addEventListener('click', openDrawer); }
  if (dClose) { dClose.addEventListener('click', closeDrawer); }
  if (backdrop) { backdrop.addEventListener('click', closeDrawer); }
  var sOpen = $('#search-open-btn'), eOpen = $('#error-search-btn');
  if (sOpen) { sOpen.addEventListener('click', openSearch); }
  if (eOpen) { eOpen.addEventListener('click', openSearch); }
  var sClose = $('#search-close-btn');
  if (sClose) { sClose.addEventListener('click', closeSearch); }

  /* ----- Lightbox ----- */
  var lb = $('#lightbox');
  function closeLightbox() {
    if (lb && lb.classList.contains('open')) { lb.classList.remove('open'); lb.innerHTML = ''; body.style.overflow = ''; }
  }
  if (lb) { lb.addEventListener('click', closeLightbox); }

  /* ----- Keyboard shortcuts ----- */
  d.addEventListener('keydown', function (e) {
    if ((e.ctrlKey || e.metaKey) && (e.key === 'k' || e.key === 'K')) { e.preventDefault(); openSearch(); }
    if (e.key === 'Escape') { closeSearch(); closeDrawer(); closeLightbox(); }
  });
  var ovEl = $('#search-overlay');
  if (ovEl) { ovEl.addEventListener('click', function (e) { if (e.target === ovEl) { closeSearch(); } }); }

  /* ----- Live search (Blogger feed) ----- */
  function thumbOf(entry, size) {
    var t = entry.media$thumbnail ? entry.media$thumbnail.url : '';
    if (!t) { return ''; }
    return t.replace('/s72-c/', '/' + size + '/').replace('=s72-c', '=' + size);
  }
  function linkOf(entry) {
    var l = entry.link || [];
    for (var i = 0; i < l.length; i++) { if (l[i].rel === 'alternate') { return l[i].href; } }
    return '#';
  }
  function dateOf(entry) { return (entry.published && entry.published.$t || '').substring(0, 10); }

  var searchInput = $('#search-input'), searchResults = $('#search-results'), searchTimer = null;
  function renderResults(entries, q) {
    if (!searchResults) { return; }
    if (!entries || !entries.length) {
      searchResults.innerHTML = '<p class="search-hint">No articles found for \u201C' + esc(q) + '\u201D — press Enter to search everything.</p>';
      return;
    }
    var html = '';
    entries.forEach(function (en) {
      var th = thumbOf(en, 'w120-h90-p-k-no-nu');
      html += '<a class="sr-item" href="' + linkOf(en) + '">' +
        (th ? '<img class="sr-thumb" src="' + th + '" alt=""/>' : '') +
        '<div><p class="sr-title">' + esc(en.title && en.title.$t) + '</p><span class="sr-date">' + dateOf(en) + '</span></div></a>';
    });
    searchResults.innerHTML = html;
  }
  function liveSearch(q) {
    if (!q || q.length < 2) {
      if (searchResults) { searchResults.innerHTML = '<p class="search-hint">Type at least 2 letters to search...</p>'; }
      return;
    }
    fetch(HOME + '/feeds/posts/summary?alt=json&max-results=6&q=' + encodeURIComponent(q))
      .then(function (r) { return r.json(); })
      .then(function (j) { renderResults((j.feed && j.feed.entry) || [], q); })
      .catch(function () {});
  }
  if (searchInput) {
    searchInput.addEventListener('input', function () {
      clearTimeout(searchTimer);
      var v = searchInput.value.trim();
      searchTimer = setTimeout(function () { liveSearch(v); }, 350);
    });
    searchInput.addEventListener('keydown', function (e) {
      if (e.key === 'Enter') {
        var v = searchInput.value.trim();
        if (v) { w.location.href = HOME + '/search?q=' + encodeURIComponent(v); }
      }
    });
  }

  /* ----- Reveal on scroll ----- */
  var reveals = $$('.reveal');
  if ('IntersectionObserver' in w && reveals.length) {
    var io = new IntersectionObserver(function (entries) {
      entries.forEach(function (en) {
        if (en.isIntersecting) { en.target.classList.add('in'); io.unobserve(en.target); }
      });
    }, { rootMargin: '0px 0px -40px 0px' });
    reveals.forEach(function (el) { io.observe(el); });
  } else {
    reveals.forEach(function (el) { el.classList.add('in'); });
  }

  /* ----- Count-up stats ----- */
  var counters = $$('[data-count]');
  function animateCount(el) {
    var target = parseFloat(el.getAttribute('data-count')) || 0;
    var suffix = el.getAttribute('data-suffix') || '';
    var t0 = null;
    function step(ts) {
      if (!t0) { t0 = ts; }
      var p = Math.min((ts - t0) / 1300, 1);
      var val = Math.floor(target * (1 - Math.pow(1 - p, 3)));
      el.textContent = val + suffix;
      if (p < 1) { requestAnimationFrame(step); }
    }
    requestAnimationFrame(step);
  }
  if ('IntersectionObserver' in w && counters.length) {
    var cio = new IntersectionObserver(function (entries) {
      entries.forEach(function (en) { if (en.isIntersecting) { animateCount(en.target); cio.unobserve(en.target); } });
    }, { threshold: 0.4 });
    counters.forEach(function (el) { cio.observe(el); });
  } else {
    counters.forEach(animateCount);
  }

  /* ----- Post / page body extras ----- */
  var postBody = $('#post-body');
  if (postBody) {
    /* Reading time (posts only) */
    var rt = $('#read-time');
    if (rt && body.classList.contains('is-post')) {
      var words = (postBody.textContent || '').trim().split(/\s+/).length;
      var mins = Math.max(1, Math.round(words / 200));
      rt.innerHTML = '<svg class="ic" viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"></circle><polyline points="12 6 12 12 16 14"></polyline></svg>' + mins + ' min read';
    }

    /* Lazy images + safe external links */
    $$('img', postBody).forEach(function (img) {
      img.loading = 'lazy';
      img.decoding = 'async';
      if (lb) {
        img.addEventListener('click', function (e) {
          e.preventDefault();
          if (img.src) { lb.innerHTML = '<img src="' + img.src + '" alt=""/>'; lb.classList.add('open'); body.style.overflow = 'hidden'; }
        });
      }
    });
    if (HOME) {
      $$('a[href^="http"]', postBody).forEach(function (a) {
        if (a.href.indexOf(HOME) !== 0) { a.target = '_blank'; a.rel = 'noopener'; }
      });
    }

    /* Table of contents */
    var heads = $$('h2, h3', postBody);
    if (heads.length >= 3) {
      var box = d.createElement('div');
      box.className = 'toc-box';
      var tocHtml = '<div class="toc-head" id="toc-head"><b><svg class="ic" viewBox="0 0 24 24"><line x1="8" y1="6" x2="21" y2="6"></line><line x1="8" y1="12" x2="21" y2="12"></line><line x1="8" y1="18" x2="21" y2="18"></line><line x1="3" y1="6" x2="3.01" y2="6"></line><line x1="3" y1="12" x2="3.01" y2="12"></line><line x1="3" y1="18" x2="3.01" y2="18"></line></svg> Table of Contents</b><svg class="ic toc-arrow" viewBox="0 0 24 24"><polyline points="6 9 12 15 18 9"></polyline></svg></div><div class="toc-body"><ul>';
      heads.forEach(function (h, i) {
        if (!h.id) { h.id = 'toc-' + (i + 1); }
        tocHtml += '<li class="lvl-' + (h.tagName === 'H2' ? '2' : '3') + '"><a href="#' + h.id + '">' + esc(h.textContent) + '</a></li>';
      });
      tocHtml += '</ul></div>';
      box.innerHTML = tocHtml;
      postBody.parentNode.insertBefore(box, postBody);
      var tHead = $('#toc-head');
      if (tHead) { tHead.addEventListener('click', function () { box.classList.toggle('collapsed'); }); }
    }

    /* Copy-code buttons */
    $$('pre', postBody).forEach(function (pre) {
      var btn = d.createElement('button');
      btn.className = 'copy-code-btn';
      btn.type = 'button';
      var copyIcon = '<svg class="ic" viewBox="0 0 24 24"><rect x="9" y="9" width="13" height="13" rx="2" ry="2"></rect><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"></path></svg>';
      var doneIcon = '<svg class="ic" viewBox="0 0 24 24"><polyline points="20 6 9 17 4 12"></polyline></svg>';
      btn.innerHTML = copyIcon + 'Copy';
      btn.addEventListener('click', function () {
        var txt = pre.innerText || '';
        function done() {
          btn.classList.add('done');
          btn.innerHTML = doneIcon + 'Copied';
          setTimeout(function () { btn.classList.remove('done'); btn.innerHTML = copyIcon + 'Copy'; }, 1600);
        }
        function fallback() {
          var ta = d.createElement('textarea');
          ta.value = txt;
          ta.style.position = 'fixed'; ta.style.opacity = '0';
          d.body.appendChild(ta); ta.select();
          try { d.execCommand('copy'); } catch (err) {}
          d.body.removeChild(ta); done();
        }
        if (navigator.clipboard && navigator.clipboard.writeText) {
          navigator.clipboard.writeText(txt).then(done, fallback);
        } else { fallback(); }
      });
      pre.appendChild(btn);
    });
  }

  /* ----- Related posts (Blogger feed) ----- */
  var rpGrid = $('#rp-grid');
  if (rpGrid && body.classList.contains('is-post')) {
    var tagEl = $('.rp-tag', rpGrid);
    var label = tagEl ? (tagEl.getAttribute('data-label') || '') : '';
    var feedUrl = label
      ? HOME + '/feeds/posts/summary/-/' + encodeURIComponent(label) + '?alt=json&max-results=7'
      : HOME + '/feeds/posts/summary?alt=json&max-results=7';
    fetch(feedUrl)
      .then(function (r) { return r.json(); })
      .then(function (j) {
        var entries = (j.feed && j.feed.entry) || [];
        var here = w.location.href.split('#')[0].split('?')[0];
        var html = '', shown = 0;
        entries.forEach(function (en) {
          if (shown >= 3) { return; }
          var url = linkOf(en);
          if (url.split('#')[0].split('?')[0] === here) { return; }
          var th = thumbOf(en, 'w400-h250-p-k-no-nu');
          html += '<article class="rp-card"><a class="rp-thumb" href="' + url + '">' +
            (th ? '<img src="' + th + '" alt="" loading="lazy"/>' : '') +
            '</a><div class="rp-body"><h4><a href="' + url + '">' + esc(en.title && en.title.$t) + '</a></h4><time>' + dateOf(en) + '</time></div></article>';
          shown++;
        });
        if (html) { rpGrid.innerHTML = html; }
        else { var rp = $('#related-posts'); if (rp) { rp.style.display = 'none'; } }
      })
      .catch(function () {});
  }

  /* ----- Copy link button ----- */
  var cpBtn = $('#copy-link-btn');
  if (cpBtn) {
    cpBtn.addEventListener('click', function () {
      var url = w.location.href;
      var copyIcon = '<svg class="ic" viewBox="0 0 24 24"><rect x="9" y="9" width="13" height="13" rx="2" ry="2"></rect><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"></path></svg>';
      var doneIcon = '<svg class="ic" viewBox="0 0 24 24"><polyline points="20 6 9 17 4 12"></polyline></svg>';
      function done() {
        var old = cpBtn.getAttribute('data-old') || copyIcon;
        cpBtn.innerHTML = doneIcon;
        setTimeout(function () { cpBtn.innerHTML = old; }, 1600);
      }
      function fallback() {
        var ta = d.createElement('textarea');
        ta.value = url;
        ta.style.position = 'fixed'; ta.style.opacity = '0';
        d.body.appendChild(ta); ta.select();
        try { d.execCommand('copy'); } catch (err) {}
        d.body.removeChild(ta); done();
      }
      cpBtn.setAttribute('data-old', copyIcon);
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(url).then(done, fallback);
      } else { fallback(); }
    });
  }
})();
/**/
